def is_majority(arr, n, x):
    # Find first occurrence of x
    lo, hi = 0, n
    while lo < hi:
        mid = (lo + hi) // 2
        if arr[mid] < x:
            lo = mid + 1
        else:
            hi = mid
    first = lo

    # Find first element greater than x
    lo, hi = 0, n
    while lo < hi:
        mid = (lo + hi) // 2
        if arr[mid] <= x:
            lo = mid + 1
        else:
            hi = mid
    last = lo

    return last - first > n // 2


assert is_majority([1, 2, 3, 3, 3, 3, 10], 7, 3) == True
```

