def last_Digit_Factorial(n):
    """
    Returns the last digit of n! (n factorial).
    """
    if n < 0:
        raise ValueError("Factorial is not defined for negative numbers.")

    if n == 0:
        return 1
    if n == 1:
        return 1
    if n == 2:
        return 2
    if n == 3:
        return 6
    if n == 4:
        return 4

    # For n >= 5, n! is divisible by 10, so its last digit is 0.
    return 0
