from typing import List

class Solution:
    def countArrays(self, original: List[int], bounds: List[List[int]]) -> int:
        base = original[0]
        lo = -10**30
        hi = 10**30

        for i, (u, v) in enumerate(bounds):
            offset = original[i] - base
            lo = max(lo, u - offset)
            hi = min(hi, v - offset)

        return max(0, hi - lo + 1)
